"""Migrated validation rules for OPP_MASTER."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, key: str) -> Any:
    if row is None:
        return ""
    value = row.get(key, "")
    return "" if value is None else value


def _text(row: dict | None, key: str) -> str:
    value = _value(row, key)
    return value if isinstance(value, str) else str(value)


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _date_ge(left: str, right: str) -> bool:
    """Legacy date ordering: the zero-date sentinel never orders."""
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image using migrated VRL rules."""
    errors: list[dict] = []

    stat_cd = _text(record, "STAT_CD")
    lost_rsn = _text(record, "LOST_RSN")
    close_dt = _text(record, "CLOSE_DT")
    amt = _number(_value(record, "AMT"))
    stage_pct = _number(_value(record, "STAGE_PCT"))

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {"code": code, "message": message, "severity": severity}
        )

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if not amt >= Decimal(0):
            fail("E3001", "Amount negative")

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and amt == Decimal(0):
            fail("E3002", "Won opportunity requires amount")

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "L" and lost_rsn == "":
            fail("E3003", "Lost reason required")

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and close_dt == "00000000":
            fail("E3004", "Won opportunity requires close date")

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _text(old, "STAT_CD")
        if old_stat_cd == "W" and stat_cd != "W":
            fail("E3005", "Cannot reopen a won opportunity")

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        valid_stage = (
            (stat_cd == "P" and stage_pct == Decimal(10))
            or (stat_cd == "Q" and stage_pct == Decimal(25))
            or (stat_cd == "N" and stage_pct == Decimal(60))
            or (stat_cd == "W" and stage_pct == Decimal(100))
            or (stat_cd == "L" and stage_pct == Decimal(0))
        )
        if not valid_stage:
            fail("E3006", "Stage percent inconsistent with status")

    # OPP-007
    if event == "INSERT":
        if not (close_dt == "00000000" or _date_ge(close_dt, str(today))):
            fail("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
